import { edit_visittype } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    editVisitDialogue: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false,
      adhocapproval: "YES",
      territoryName: "",
      territoryCity: "",
      territoryDescription: "",
      terriotoryManager: "",
      userArray: [],
      searchF: "",
      visitFrequency: "",
      visitTypeAction: null,
      scanTolerance: 0,
      visitType: "",
      visitName: ""
    };
  },
  watch: {
    editVisitDialogue: {
      async handler() {
        if (this.editVisitDialogue == true) {
          this.visitName = this.rowInfo.visit_type_name;
          this.visitFrequency = this.rowInfo.visit_type_frequency;
          this.visitTypeAction = this.rowInfo.visit_type_representation;
          this.scanTolerance = this.rowInfo.scan_tolerance;
          this.adhocapproval = this.rowInfo.adhock_approval_required == undefined ? "NO" : this.rowInfo.adhock_approval_required == true ? "YES" : "NO";

          // console.log(this.rowInfo);
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;

      // var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_visittype, {
          input: {
            visit_type_id: this.rowInfo.visit_type_id,
            visit_type_name: this.visitName,
            visit_type_frequency: this.visitFrequency,
            visit_type_representation: this.visitTypeAction,
            scan_tolerance: this.visitTypeAction == "VIRTUAL" ? 0 : Number(this.scanTolerance),
            adhock_approval_required: this.adhocapproval == "YES" ? true : false
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_visittype);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
